generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:returnsPct ?ret .
    FILTER(xsd:decimal(?ret) < 0)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 40)
  }

  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:diversificationScore ?divScore .
    FILTER(xsd:decimal(?divScore) < 30)
  }
}

